import requests
import os
from typing import List, Dict, Any

def detect_labels_in_image(image_path: str) -> List[Dict[str, Any]]:
    """
    Detect labels and objects in a static image using Google Cloud Vision API

    Args:
        image_path (str): Path to the image file

    Returns:
        List[Dict[str, Any]]: List of detected labels with confidence scores
    """
    # Google Cloud Vision API endpoint
    api_url = "https://vision.googleapis.com/v1/images:annotate"

    # Read and encode image file
    with open(image_path, "rb") as image_file:
        image_content = image_file.read()

    # Prepare the request payload
    payload = {
        "requests": [
            {
                "image": {
                    "content": image_content.decode("utf-8")
                },
                "features": [
                    {
                        "type": "LABEL_DETECTION",
                        "maxResults": 10
                    }
                ]
            }
        ]
    }

    # Make the API request
    headers = {"Content-Type": "application/json"}
    params = {"key": os.environ.get("GOOGLE_CLOUD_VISION_API_KEY")}

    response = requests.post(api_url, headers=headers, params=params, json=payload)

    if response.status_code != 200:
        raise Exception(f"API request failed with status {response.status_code}: {response.text}")

    result = response.json()

    # Parse the response
    labels = []
    if "responses" in result and len(result["responses"]) > 0:
        label_annotations = result["responses"][0].get("labelAnnotations", [])
        for annotation in label_annotations:
            labels.append({
                "description": annotation["description"],
                "confidence": annotation["score"]
            })

    return labels

